import { NextRequest } from 'next/server';
import { TABLE_REGISTRY } from '@/lib/tableRegistry';
import { dataGet, dataPost, dataPatch, dataDelete, dataNotFound } from '@/lib/dataRoute';

/* Platform domain data route (GENERATED by the wire closure, 2026-11-15):
   the named API surface for the platform tables that had no hand-written
   route. Tenant-scoped CRUD through the shared handler in
   lib/dataRoute.ts, driven by each table's TABLE_REGISTRY entry.
   Tables served here:
   - platform_account_subscriptions
   - platform_admin_access_log
   - platform_admins
   - platform_calendar_attendees
   - platform_canonical_map
   - platform_capabilities
   - platform_db_contract_metadata
   - platform_deployment_profile
   - platform_duplicable_tables
   - platform_email_messages
   - platform_email_threads
   - platform_fk_exemptions
   - platform_fk_log
   - platform_form_field_visibility
   - platform_idempotency_keys
   - platform_integration_health_registry
   - platform_jobs
   - platform_lens_fields
   - platform_lens_labels
   - platform_lenses
   - platform_module_permissions
   - platform_objects
   - platform_party_roles
   - platform_party_sources
   - platform_permission_registry
   - platform_polymorphic_columns
   - platform_report_definitions
   - platform_reserved_slugs
   - platform_role_values
   - platform_subscription_offers
   - platform_table_access_overrides
   - platform_table_registry
   - platform_tools
   - platform_vendor_identity_links
   - platform_workflow_transition_validation
*/

const SERVED = new Set([
  'platform_account_subscriptions',
  'platform_admin_access_log',
  'platform_admins',
  'platform_calendar_attendees',
  'platform_canonical_map',
  'platform_capabilities',
  'platform_db_contract_metadata',
  'platform_deployment_profile',
  'platform_duplicable_tables',
  'platform_email_messages',
  'platform_email_threads',
  'platform_fk_exemptions',
  'platform_fk_log',
  'platform_form_field_visibility',
  'platform_idempotency_keys',
  'platform_integration_health_registry',
  'platform_jobs',
  'platform_lens_fields',
  'platform_lens_labels',
  'platform_lenses',
  'platform_module_permissions',
  'platform_objects',
  'platform_party_roles',
  'platform_party_sources',
  'platform_permission_registry',
  'platform_polymorphic_columns',
  'platform_report_definitions',
  'platform_reserved_slugs',
  'platform_role_values',
  'platform_subscription_offers',
  'platform_table_access_overrides',
  'platform_table_registry',
  'platform_tools',
  'platform_vendor_identity_links',
  'platform_workflow_transition_validation'
]);

function entry(table: string) {
  return SERVED.has(table) ? TABLE_REGISTRY[table] ?? null : null;
}

export async function GET(req: NextRequest, ctx: { params: Promise<{ table: string }> }) {
  const { table } = await ctx.params;
  const r = entry(table);
  return r ? dataGet(req, table, r) : dataNotFound(table);
}

export async function POST(req: NextRequest, ctx: { params: Promise<{ table: string }> }) {
  const { table } = await ctx.params;
  const r = entry(table);
  return r ? dataPost(req, table, r) : dataNotFound(table);
}

export async function PATCH(req: NextRequest, ctx: { params: Promise<{ table: string }> }) {
  const { table } = await ctx.params;
  const r = entry(table);
  return r ? dataPatch(req, table, r) : dataNotFound(table);
}

export async function DELETE(req: NextRequest, ctx: { params: Promise<{ table: string }> }) {
  const { table } = await ctx.params;
  const r = entry(table);
  return r ? dataDelete(req, table, r) : dataNotFound(table);
}
